// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount, address depositor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // deposit via the payable fallback from an arbitrary (funded) actor
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool sent,) = address(c).call{value: amount}("");
        assertTrue(sent);

        // owner (the test contract, which is msg.sender at deployment) withdraws everything
        vm.prank(address(this));
        c.withdrawAll();

        // GENERAL RULE: after withdrawAll, the reference contract holds NOTHING;
        // the mutant always sends only 1 wei and leaves amount - 1 (nonzero) behind.
        assertTrue(address(c).balance == 0);
    }
}
